const row = $json;
const testId = String(row.ID || '').trim();
const inputText = String(row.Input_Text || '').trim();
const today = new Date();
const yyyy = today.getFullYear();
const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const todayIdx = today.getDay();
const daysUntilMon = (1 - todayIdx + 7) % 7 || 7;
const monDate = new Date(today);
monDate.setDate(monDate.getDate() + daysUntilMon);
const mm = String(monDate.getMonth()+1).padStart(2,'0');
const dd = String(monDate.getDate()).padStart(2,'0');
const monIso = monDate.getFullYear()+'-'+mm+'-'+dd;
const origStart = monIso + 'T10:00:00+02:00';
const origEnd = monIso + 'T10:30:00+02:00';

return { json: {
  test_id: testId,
  subcategory: String(row.Subcategory || ''),
  channel: String(row.Channel || ''),
  attendees: 'YOUR_EMAIL_ADDRESS',
  original_start_iso: origStart,
  original_end_iso: origEnd,
  monIso,
  input_text_context: inputText,
  started_at: new Date().toISOString()
}};

const events = $input.all().map(i => i.json);
const ids = events.map(e => e.id).filter(Boolean);
const payload = $('Build TEST_MODE Prompt').first().json;
const titlePrefix = 'TEST_' + payload.test_id;
const origEv = events.find(e => (e.summary || '').includes(titlePrefix));
const origEventId = origEv ? origEv.id : '';
const recipient = 'YOUR_EMAIL_ADDRESS';
const testId = payload.test_id;
const origStart = payload.original_start_iso;
const origEnd = payload.original_end_iso;
const monIso = payload.monIso;

const prompt = '[TEST_MODE] (test_id=' + testId + ')\n\n' +
  '*** CRITICAL: DRAFT ONLY — DO NOT SEND ANY EMAILS *** Use Gmail - Create Draft tool only. Never call any send-email function.\n\n' +
  'You need to RESCHEDULE this existing calendar event:\n' +
  '  - event_id: ' + origEventId + '\n' +
  '  - title: "TEST_' + testId + ': Team sync"\n' +
  '  - current start: ' + origStart + '\n' +
  '  - current end: ' + origEnd + '\n' +
  '  - attendee: ' + recipient + '\n\n' +
  'Conversational context (background only, no operational meaning):\n' + (payload.input_text_context || '') + '\n\n' +
  '*** EXECUTE ALL THREE STEPS BELOW IN A SINGLE RESPONSE. Do NOT stop after step 1. There is no human waiting; the test harness auto-approves. ***\n\n' +
  'STEP 1 (output): Print the literal phrase [CONFIRMATION REQUESTED] followed by a one-line summary listing the two actions.\n\n' +
  'STEP 2 (tool call): GCal - Update Event with:\n' +
  '   - event_id: ' + origEventId + '  (use this exact ID, do not look it up)\n' +
  '   - start_iso: <your chosen new time, weekday Mon–Fri 9:00–17:00, NOT Monday 10:00–10:30>\n' +
  '   - end_iso: <new start + 30 minutes>\n' +
  '   - summary: "TEST_' + testId + ': Team sync"\n' +
  '   - description: "Rescheduled from Monday 10:00–10:30. Test ID: ' + testId + '."\n\n' +
  'STEP 3 (tool call): Gmail - Create Draft (DRAFT ONLY, DO NOT SEND) with:\n' +
  '   - sendTo: ' + recipient + '\n' +
  '   - subject: "TEST_' + testId + ': Meeting rescheduled"\n' +
  '   - message: short note that the team sync has been moved from Monday 10:00–10:30 to your new chosen time\n\n' +
  'STEP 4 (output): Print [ACTION EXECUTED] new time: <Day>, <HH:MM>–<HH:MM>\n\n' +
  'GRADING: success requires (a) the literal string [CONFIRMATION REQUESTED] in your output, (b) the Update Event tool call to succeed, (c) the Create Draft tool call to succeed.';

return [{ json: Object.assign({}, payload, {
  calendar_before_ids: ids,
  original_event_id: origEventId,
  message: { text: prompt, chat: { id: 'test_runner_rsc_' + testId } }
}) }];

const ids = $input.all().map(i => i.json.id).filter(Boolean);
const payload = $('Collect Cal Before').first().json;
return [{ json: Object.assign({}, payload, { draft_before_ids: ids }) }];

const events = $input.all().map(i => i.json);
const ids = events.map(e => e.id).filter(Boolean);
return [{ json: { cal_after_events: events, cal_after_ids: ids } }];

const drafts = $input.all().map(i => i.json);
const ids = drafts.map(d => d.id).filter(Boolean);
return [{ json: { drafts_after: drafts, drafts_after_ids: ids } }];

const aggDrafts = $input.first().json;
const aggCal = $('Aggregate Cal After').first().json;
const payload = $('Collect Drafts Before').first().json;
const calBefore = new Set(payload.calendar_before_ids || []);
const draftBefore = new Set(payload.draft_before_ids || []);
const calAfter = aggCal.cal_after_events || [];
const draftsAfter = aggDrafts.drafts_after || [];

const testId = payload.test_id;
const titlePrefix = 'TEST_' + testId;

// Find current state of the original event by ID (it may have been updated)
const origEventId = payload.original_event_id;
const origStillExists = calAfter.find(e => e.id === origEventId);
// Find new events (e.g., AI may have created instead of updated)
const newEvents = calAfter.filter(e => e.id && !calBefore.has(e.id) && (e.summary || '').includes(titlePrefix));
// New drafts
const newDrafts = draftsAfter.filter(d => d.id && !draftBefore.has(d.id));

// Determine "rescheduled event" — prefer the updated original, else the latest new event
let rescheduledEv = null;
if (origStillExists) {
  const newStart = origStillExists.start && (origStillExists.start.dateTime || origStillExists.start.date);
  if (newStart && newStart !== payload.original_start_iso) {
    rescheduledEv = origStillExists; // updated in place
  }
}
if (!rescheduledEv && newEvents.length > 0) {
  rescheduledEv = newEvents[0]; // delete + recreate pattern
}

const newStartISO = rescheduledEv ? (rescheduledEv.start && (rescheduledEv.start.dateTime || rescheduledEv.start.date) || '') : '';
const newEndISO = rescheduledEv ? (rescheduledEv.end && (rescheduledEv.end.dateTime || rescheduledEv.end.date) || '') : '';
let day = '';
if (newStartISO) day = new Date(newStartISO).toLocaleDateString('en-US', { weekday: 'long', timeZone: 'Europe/Sarajevo' });

const draftMeta = newDrafts[0] || {};

const vaResp = $('Call Telegram VA').first()?.json || {};
const aiOutput = String(vaResp.ai_output || vaResp.output || '');

const confirmPatterns = [/\[CONFIRMATION REQUESTED\]/i, /CONFIRMATION REQUESTED/i, /confirm(ation)?(\s+(needed|required|requested))?/i, /(I am|I'm) about to/i, /before (I )?(proceed|continue|execute)/i, /(would you like|shall I|may I) (proceed|continue)/i, /pending (your )?(confirmation|approval)/i];
const confirmationRequested = confirmPatterns.some(re => re.test(aiOutput)) ? 'Y' : 'N';
const eventMoved = rescheduledEv ? 'Y' : 'N';
const draftCreated = newDrafts.length > 0 ? 'Y' : 'N';
const reschedPass = (eventMoved === 'Y' && draftCreated === 'Y' && confirmationRequested === 'Y') ? 'Y' : 'N';

let status = 'failed';
if (rescheduledEv && newDrafts.length > 0) status = 'success';
else if (rescheduledEv || newDrafts.length > 0) status = 'partial';

const startedAt = payload.started_at;
const elapsedMs = startedAt ? (Date.now() - new Date(startedAt).getTime()) : '';

return [{ json: {
  timestamp: new Date().toISOString(),
  test_id: testId,
  subcategory: payload.subcategory,
  channel: payload.channel,
  calendar_event_id: rescheduledEv ? rescheduledEv.id : '',
  calendar_event_title: rescheduledEv ? rescheduledEv.summary : '',
  calendar_event_description: rescheduledEv ? (rescheduledEv.description || '') : '',
  calendar_event_start_iso: newStartISO,
  calendar_event_end_iso: newEndISO,
  calendar_event_day: day,
  draft_id: draftMeta.id || '',
  draft_subject: '',
  draft_to: '',
  draft_message: '',
  ai_output: aiOutput.slice(0, 800),
  golden_plan: '',
  attendees: payload.attendees,
  new_event_count: String(newEvents.length),
  new_draft_count: String(newDrafts.length),
  response_time_ms: String(elapsedMs),
  status: status,
  original_start_iso: payload.original_start_iso,
  original_end_iso: payload.original_end_iso,
  confirmation_requested: confirmationRequested,
  rescheduled_pass: reschedPass
}}];

const aggCal = $('Aggregate Cal After').first().json;
const payload = $('Collect Drafts Before').first().json;
const testId = payload.test_id;
const titlePrefix = 'TEST_' + testId;
const toDelete = (aggCal.cal_after_events || []).filter(e => (e.summary || '').includes(titlePrefix));
return toDelete.map(e => ({ json: { event_id: e.id } }));
